import os

def get_process_command(process_id):
    command = f"ps -p {int(process_id)} -o command="
    return os.popen(command).read().strip()

import subprocess

def adjust_volume(command):
    adjustments = {"up": "5%+", "down": "5%-"}
    if command not in adjustments:
        return "unrecognized command"
    try:
        subprocess.run(
            ["amixer", "set", "Master", adjustments[command]],
            check=True,
            capture_output=True,
            text=True,
        )
        result = subprocess.run(
            ["amixer", "get", "Master"],
            check=True,
            capture_output=True,
            text=True,
        )
        return result.stdout.strip()
    except (OSError, subprocess.CalledProcessError):
        return "volume adjustment failed"

def build_metadata(file_path, metadata_name):
    with open(file_path, encoding="utf-8") as stream:
        for line in stream:
            if line.strip().startswith("__version__"):
                version = line.split("=", 1)[1].strip().strip("'\"")
                return {metadata_name: {"version": version}}
    raise ValueError("version line not found")

def update_model(model, layer_names, weights, output_path, save_format):
    for layer_name in layer_names:
        model.get_layer(layer_name).set_weights(weights[layer_name])
    model.save(output_path, save_format=save_format)
    return output_path

